using System;using System.IO;using System.Collections.Generic;
public class Offline70QpStatFG82 {public byte Id;public ushort Level;}
partial class Offline70QpShopFG82 {
 internal static ushort Maximum(byte id,byte level){if(id>=Costs.Length||level<1||level>70)throw new InvalidDataException("QP stat definition or character level");int count=0;byte[] gates=Gates[id];for(int i=0;i<gates.Length;i+=2)if(level>=gates[i])count+=gates[i+1];return (ushort)count;}
 internal static uint Spent(Offline70EconomyState s){if(s.QuestPointStats==null||s.QuestPointStats.Count>14)throw new InvalidDataException("QP stat collection");HashSet<byte> ids=new HashSet<byte>();uint total=0;foreach(Offline70QpStatFG82 row in s.QuestPointStats){if(row==null||row.Id>=14||row.Level==0||row.Level>Maximum(row.Id,s.Level)||!ids.Add(row.Id))throw new InvalidDataException("QP saved stat bounds");total+=Costs[row.Id]*(uint)row.Level;}return total;}
 internal static ushort Level(Offline70EconomyState s,byte id){foreach(Offline70QpStatFG82 row in s.QuestPointStats)if(row.Id==id)return row.Level;return 0;}
 internal static byte[] ParseBuy(byte[] cipher,byte[] keys){if(cipher==null||cipher.Length!=16)throw new InvalidDataException("QP407 request size");byte[] b=Offline70RoleProtocol.BatchCryptFG(cipher,keys,1,false);for(int i=2;i<b.Length;i++)if(b[i]!=0)throw new InvalidDataException("QP407 request padding");if(b[0]>=14||b[1]==0)throw new InvalidDataException("QP407 stat or quantity");return new byte[]{b[0],b[1]};}
 internal static Offline70EconomyState Buy(string path,string receipt,byte id,byte count,out bool duplicate){if(id>=14||count==0)throw new InvalidDataException("QP purchase bounds");return Offline70Economy.Apply(path,receipt,"qp-stat-buy",id+":"+count,delegate(Offline70EconomyState s){ushort level=Level(s,id);uint cost=(uint)(Costs[id]*count);if(level+count>Maximum(id,s.Level)||s.QuestPoints<cost)throw new InvalidDataException("QP insufficient points or level allowance");Offline70QpStatFG82 row=null;foreach(Offline70QpStatFG82 r in s.QuestPointStats)if(r.Id==id)row=r;if(row==null){row=new Offline70QpStatFG82{Id=id};s.QuestPointStats.Add(row);}row.Level=(ushort)(level+count);s.QuestPoints-=cost;},out duplicate);}
 internal static uint ResetCost(Offline70EconomyState s){return Math.Min((uint)s.QuestPointResetCount*100000u,3000000u);}
 internal static Offline70EconomyState Reset(string path,string receipt,ushort itemSlot,bool cashItem,out bool duplicate){return Offline70Economy.Apply(path,receipt,cashItem?"qp-reset-item":"qp-reset-gold",cashItem?itemSlot+":2682275":"menu",delegate(Offline70EconomyState s){uint refund=Spent(s);if(refund==0||s.QuestPointResetCount==UInt16.MaxValue||refund>Int32.MaxValue-s.QuestPoints)throw new InvalidDataException("QP reset empty, count or wallet bounds");if(cashItem){Offline70EconomyEntry item=Offline70Economy.Find(s,0,itemSlot);if(item==null||item.ItemId!=2682275)throw new InvalidDataException("QP reset item ownership");if(item.Quantity==1)s.Inventory.Remove(item);else item.Quantity--;}else{uint cost=ResetCost(s);if(s.Gold<cost)throw new InvalidDataException("QP reset insufficient gold");s.Gold-=cost;}s.QuestPoints+=refund;s.QuestPointStats.Clear();s.QuestPointResetCount++;},out duplicate);}
 internal static byte[] BuyReply(bool success,byte id,ushort level,byte[] keys){byte[] b=success?new byte[]{1,id,(byte)level,(byte)(level>>8)}:new byte[]{0,0x17};return Offline70RoleProtocol.BatchPacketFG(1,407,b,keys,false);}
 internal static byte[] ResetReply(bool success,Offline70EconomyState s,byte[] keys){byte[] b;if(success){b=new byte[5];b[0]=1;BitConverter.GetBytes(s.Gold).CopyTo(b,1);}else b=new byte[]{0,0x0a};return Offline70RoleProtocol.BatchPacketFG(1,408,b,keys,false);}
 internal static byte[] ItemReply(ushort slot,bool success,byte[] keys){byte[] b;if(success){b=new byte[12];b[0]=1;BitConverter.GetBytes(slot).CopyTo(b,1);b[3]=23;}else b=new byte[]{0,0x17};return Offline70RoleProtocol.BatchPacketFG(1,32,b,keys,true);}
 internal static byte[] Record(Offline70EconomyState s){Offline70Economy.Validate(s);List<Offline70QpStatFG82> rows=new List<Offline70QpStatFG82>(s.QuestPointStats);rows.Sort(delegate(Offline70QpStatFG82 a,Offline70QpStatFG82 b){return a.Id.CompareTo(b.Id);});using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)rows.Count);foreach(Offline70QpStatFG82 r in rows){w.Write(r.Id);w.Write(r.Level);}w.Write(s.QuestPoints);w.Write(s.QuestPointResetCount);w.Write((byte)0);return m.ToArray();}}
 // Native7FBC50 is the final8-byte empty QP block, followed by4+2 fixed bytes.
 internal static byte[] Restore(byte[] addition,Offline70EconomyState s){if(addition==null||addition.Length<14)throw new InvalidDataException("Addition QP record bounds");int at=addition.Length-14;for(int i=at;i<at+8;i++)if(addition[i]!=0)throw new InvalidDataException("Expected original empty QP block");byte[] qp=Record(s),result=new byte[addition.Length+qp.Length-8];Array.Copy(addition,0,result,0,at);qp.CopyTo(result,at);Array.Copy(addition,at+8,result,at+qp.Length,6);return result;}
}
